-- ============================================================================
--  MIGRATIONS/SEED_100_FULL.SQL
--
--  100 students across every dimension the registrar filters by, with the
--  records that hang off them: portal accounts, term records, subject grades,
--  and one document request each.
--
--    mysql -u root registrar_ai < migrations/seed_100_full.sql
--
--  GENERATED, THEN VERIFIED - NOT HAND-WRITTEN
--  --------------------------------------
--  Written out of the seeded rows, so it cannot drift from what the PHP
--  seeder produced. Hand-typed INSERTs are how a fixture ends up disagreeing
--  with itself: a section no student is filed under, or a term GWA that no
--  longer matches the grades beneath it.
--
--  TWO MARKERS, AND REMOVAL NEEDS BOTH TO AGREE
--  ----------------------------------------
--    student_number LIKE 'S26%'         the number marker
--    email LIKE '%@testdata.example'    the address marker
--
--  One alone is not enough. student_number carries only a non-unique index,
--  so a real student could eventually be issued an S26xxxxx number.
--  Requiring BOTH means the companion unseed file can only ever remove what
--  this one wrote. See migrations/unseed_100_full.sql.
--
--  WHAT IS IN HERE
--  ---------------
--  100 students, 100 portal accounts, 100 term records,
--  500 subject grades, 100 document requests.
--
--  Five programs, all four year levels, three school years, three semesters
--  and every value of students.status. A fixture where every row shares one
--  program and one term cannot tell a grouping bug from a correct grouping -
--  and grouping is what the masterlist blocks, the folder browser and the
--  Insight figures all do.
--
--  The requests cover all eight document_status values, and that is the one
--  that matters most: the AI Insight chart collapses eight statuses into five
--  series, so a fixture that only ever files 'Filed' leaves four series
--  permanently empty - which is how a wrong status mapping passes review,
--  because nothing ever looks wrong.
--
--  @testdata.example addresses are undeliverable by construction. They give
--  the row the shape of a real one; email_is_placeholder is set, so the
--  welcome-mail and any bounce sweep skip them.
--
--  Sign in as any seeded student with their student number and the password
--  'password'.
--
-- ============================================================================

--  NO TRANSACTION ON PURPOSE
--  ------------------------
--  This file does NOT open one, and that is deliberate.
--
--  phpMyAdmin already wraps an import in a transaction, so a bare
--  START TRANSACTION inside it raises MySQL 1568, "There is already an
--  active transaction", and phpMyAdmin aborts the WHOLE file and reports
--  only "The import could not be completed". That is a failure in the
--  tool, not in the data, and it looks exactly like a corrupt file.
--
--  phpMyAdmin commits for us; the mysql client commits by default too.
--  Nothing is lost by leaving the transaction alone.
--
--  SAFE TO RUN TWICE
--  -----------------
--  The rows below carry explicit ids, so a second import would collide
--  on the primary key. Rather than a bare duplicate-key error, the file
--  removes any previous seeded rows first - which also makes it the fix
--  for an import that died halfway through an earlier attempt.
--
--  Only rows carrying BOTH markers are removed. See the note below.
-- ============================================================================

-- utf8 first: the names and punctuation in this file are UTF-8, and a
-- connection in latin1 would silently store them as mojibake.
SET NAMES utf8mb4;

-- Not for correctness - nothing here violates a key - but so that a partial
-- import on a host that decided otherwise cannot be blocked by it.
SET FOREIGN_KEY_CHECKS = 0;

-- ── Clear any earlier import ──────────────────────────────────────────
--  Same two markers, same "both must agree" rule as the unseed file.
--  Children first, for the reason given there: no declared foreign
--  keys on these tables today, so the order is not left to chance.
DELETE g FROM academic_grades g
  JOIN academic_history h ON h.id = g.academic_history_id
  JOIN students s ON s.id = h.student_id
 WHERE s.student_number LIKE 'S26%' AND s.email LIKE '%@testdata.example';

DELETE h FROM academic_history h
  JOIN students s ON s.id = h.student_id
 WHERE s.student_number LIKE 'S26%' AND s.email LIKE '%@testdata.example';

DELETE d FROM document_requests d
  JOIN students s ON s.id = d.student_id
 WHERE s.student_number LIKE 'S26%' AND s.email LIKE '%@testdata.example';

DELETE u FROM users u
  JOIN students s ON s.id = u.student_id
 WHERE s.student_number LIKE 'S26%' AND s.email LIKE '%@testdata.example';

DELETE FROM students
 WHERE student_number LIKE 'S26%' AND email LIKE '%@testdata.example';

-- ── Students ──────────────────────────────────────────────────────────
