-- ── What landed ──────────────────────────────────────────────────────
SELECT 'students' AS what, COUNT(*) AS n FROM students WHERE student_number LIKE 'S26%'
UNION ALL SELECT 'portal accounts', COUNT(*) FROM users u JOIN students s ON s.id=u.student_id WHERE s.student_number LIKE 'S26%'
UNION ALL SELECT 'term records', COUNT(*) FROM academic_history h JOIN students s ON s.id=h.student_id WHERE s.student_number LIKE 'S26%'
UNION ALL SELECT 'subject grades', COUNT(*) FROM academic_grades g JOIN academic_history h ON h.id=g.academic_history_id JOIN students s ON s.id=h.student_id WHERE s.student_number LIKE 'S26%'
UNION ALL SELECT 'document requests', COUNT(*) FROM document_requests d JOIN students s ON s.id=d.student_id WHERE s.student_number LIKE 'S26%';
